  // Support Admin: AI File Analysis & Knowledge Chunk Extraction
  app.post('/api/admin/support/knowledge-docs/extract-from-file', async (req, res) => {
    try {
      const { fileData, fileName, mimeType, categoryHint, autoSave } = req.body;

      if (!fileData) {
        return res.status(400).json({ error: 'File data is required for extraction.' });
      }

      const cleanFileName = fileName || 'Uploaded Document';
      const cleanMime = mimeType || 'text/plain';
      const cleanCategory = (categoryHint || 'General').trim();

      let extractedChunks: { title: string; category: string; content: string }[] = [];

      // 1. If Gemini API Key is present, use multi-model AI extraction with failover & retry
      if (process.env.GEMINI_API_KEY) {
        const candidateModels = [
          'gemini-3.8-flash',
          'gemini-3.1-flash-lite',
          'gemini-flash-latest',
          'gemini-3.1-pro-preview'
        ];
        const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY });

        const systemInstruction = `You are an expert technical documentation analyzer and knowledge chunking engine for the Trek Consultancy Forum.
Your task is to analyze the provided file/document and extract clean, highly factual, self-contained Knowledge Chunks suitable for real-time RAG (Retrieval-Augmented Generation).

Guidelines:
1. Break down the document into 1 to 8 coherent, meaningful knowledge chunks (depending on document length and topics covered).
2. Each chunk MUST have:
   - "title": A concise, descriptive, search-friendly title (e.g. "Docly Demo Import Steps", "Author Delete Permissions", "Enterprise Consultancy Retainer Scope").
   - "category": A clear category tag (e.g. "${cleanCategory}", "WordPress & Themes", "PostgreSQL Database", "Forum Rules", "Consultancy", "Security").
   - "content": A well-structured, factual summary or guide explaining the information clearly in 1-4 concise paragraphs or bullet points.
3. Remove redundant filler or formatting noise.

Output MUST be valid JSON in this exact structure:
{
  "chunks": [
    {
      "title": "...",
      "category": "...",
      "content": "..."
    }
  ]
}`;

        // Prepare contents based on mimeType
        let contentsPayload: any[];
        const isTextBased = cleanMime.startsWith('text/') || cleanMime === 'application/json' || cleanFileName.endsWith('.md') || cleanFileName.endsWith('.txt') || cleanFileName.endsWith('.csv') || cleanFileName.endsWith('.json');

        if (isTextBased && !fileData.startsWith('data:')) {
          contentsPayload = [
            `File Name: ${cleanFileName}\nFile Type: ${cleanMime}\nPreferred Category: ${cleanCategory}\n\nDocument Content:\n${fileData}`
          ];
        } else {
          // Base64 data (PDF, Images, Word documents, binary formats)
          let base64Pure = fileData;
          if (fileData.includes('base64,')) {
            base64Pure = fileData.split('base64,')[1];
          }
          contentsPayload = [
            {
              inlineData: {
                data: base64Pure,
                mimeType: cleanMime
              }
            },
            `File Name: ${cleanFileName}\nPreferred Category: ${cleanCategory}\nPlease analyze this document and extract the structured knowledge chunks.`
          ];
        }

        for (const modelName of candidateModels) {
          let modelExtracted = false;
          for (let attempt = 0; attempt < 2; attempt++) {
            try {
              const response = await ai.models.generateContent({
                model: modelName,
                contents: contentsPayload,
                config: {
                  systemInstruction,
                  responseMimeType: 'application/json',
                  temperature: 0.2,
                  maxOutputTokens: 2000
                }
              });

              if (response.text) {
                let cleanJson = response.text.trim();
                if (cleanJson.startsWith('```json')) {
                  cleanJson = cleanJson.replace(/^```json\s*/, '').replace(/```\s*$/, '');
                } else if (cleanJson.startsWith('```')) {
                  cleanJson = cleanJson.replace(/^```\s*/, '').replace(/```\s*$/, '');
                }

                const parsed = JSON.parse(cleanJson);
                if (parsed.chunks && Array.isArray(parsed.chunks) && parsed.chunks.length > 0) {
                  extractedChunks = parsed.chunks.map((c: any) => ({
                    title: String(c.title || `${cleanFileName} Section`),
                    category: String(c.category || cleanCategory),
                    content: String(c.content || '')
                  })).filter((c: any) => c.content.trim().length > 0);

                  if (extractedChunks.length > 0) {
                    modelExtracted = true;
                    break;
                  }
                }
              }
            } catch (modelErr: any) {
              const msg = modelErr?.message || '';
              const isTransient = msg.includes('503') || msg.includes('UNAVAILABLE') || msg.includes('429') || msg.includes('high demand');
              if (isTransient && attempt === 0) {
                await new Promise(r => setTimeout(r, 300));
                continue;
              }
              break;
            }
          }
          if (modelExtracted) break;
        }
      }

      // 2. High-quality intelligent fallback extraction if Gemini is unavailable
      if (extractedChunks.length === 0) {
        let textToChunk = '';
        if (typeof fileData === 'string' && !fileData.startsWith('data:')) {
          textToChunk = fileData;
        } else if (typeof fileData === 'string' && fileData.includes('base64,')) {
          try {
            textToChunk = Buffer.from(fileData.split('base64,')[1], 'base64').toString('utf-8');
          } catch {
            textToChunk = '';
          }
        }

        const baseTitle = cleanFileName.replace(/\.[^/.]+$/, '');

        if (textToChunk.trim()) {
          // Check if JSON format
          try {
            const parsedObj = JSON.parse(textToChunk);
            if (Array.isArray(parsedObj)) {
              parsedObj.slice(0, 8).forEach((item, idx) => {
                const title = item.title || item.name || item.subject || `${baseTitle} - Item ${idx + 1}`;
                const content = typeof item === 'object' ? JSON.stringify(item, null, 2) : String(item);
                extractedChunks.push({ title, category: cleanCategory, content });
              });
            } else if (typeof parsedObj === 'object' && parsedObj !== null) {
              Object.keys(parsedObj).slice(0, 8).forEach(k => {
                const val = parsedObj[k];
                const content = typeof val === 'object' ? JSON.stringify(val, null, 2) : String(val);
                extractedChunks.push({ title: `${baseTitle}: ${k}`, category: cleanCategory, content });
              });
            }
          } catch {
            // Not JSON
          }

          // Check if Markdown with section headers
          if (extractedChunks.length === 0) {
            const markdownSections = textToChunk.split(/\n(?=#{1,3}\s+)/g).filter(s => s.trim().length > 20);
            if (markdownSections.length > 1) {
              markdownSections.slice(0, 8).forEach((sec, idx) => {
                const firstLine = sec.trim().split('\n')[0].replace(/^#{1,3}\s+/, '').trim();
                const body = sec.trim().replace(/^#{1,3}\s+[^\n]+\n?/, '').trim() || sec.trim();
                extractedChunks.push({
                  title: firstLine.length > 0 && firstLine.length < 80 ? firstLine : `${baseTitle} - Part ${idx + 1}`,
                  category: cleanCategory,
                  content: body
                });
              });
            }
          }

          // Check distinct paragraphs
          if (extractedChunks.length === 0) {
            const paragraphs = textToChunk.split(/\n\s*\n+/).map(p => p.trim()).filter(p => p.length > 30);
            if (paragraphs.length > 0) {
              extractedChunks = paragraphs.slice(0, 6).map((p, idx) => ({
                title: `${baseTitle} - Section ${idx + 1}`,
                category: cleanCategory,
                content: p.trim()
              }));
            }
          }

          // Single summary fallback
          if (extractedChunks.length === 0) {
            extractedChunks = [{
              title: `${baseTitle} Overview`,
              category: cleanCategory,
              content: textToChunk.trim().slice(0, 1500)
            }];
          }
        } else {
          extractedChunks = [{
            title: `${baseTitle} Document`,
            category: cleanCategory,
            content: `Extracted content from ${cleanFileName} (${cleanMime}). Added into PostgreSQL knowledge base.`
          }];
        }
      }

      // 3. If autoSave is enabled, persist chunks directly into PostgreSQL
      const savedDocs: any[] = [];
      if (autoSave && extractedChunks.length > 0) {
        for (const chunk of extractedChunks) {
          const id = `doc-${Date.now()}-${Math.floor(Math.random() * 1000)}`;
          const insertRes = await pool.query(`
            INSERT INTO knowledge_documents (id, title, content, category, status)
            VALUES ($1, $2, $3, $4, 'published')
            RETURNING id, title, content, category, status, created_at as "createdAt", updated_at as "updatedAt"
          `, [id, chunk.title.trim(), chunk.content.trim(), chunk.category || cleanCategory]);

          savedDocs.push(insertRes.rows[0]);
        }
      }

      res.json({
        success: true,
        fileName: cleanFileName,
        extractedChunksCount: extractedChunks.length,
        chunks: extractedChunks,
        savedDocs: savedDocs
      });
    } catch (err: any) {
      console.error('File knowledge extraction failed:', err);
      res.status(500).json({ error: err.message });
    }
  });

